mapper.select:
select id, soap_id, consumable_id, quantity_used, unit_price, unit, created
from soap_consumables_usage

    and soap_id = #{soapId}
    and consumable_id = #{consumableId}

limit #{pageable.offset}, #{pageable.pageSize}

select count(1) from soap_consumables_usage

    and soap_id = #{soapId}
    and consumable_id = #{consumableId}

mapper.update:
update soap_consumables_usage
soap_id = #{soapId}, consumable_id = #{consumableId}, quantity_used = #{quantityUsed}, unit_price = #{unitPrice}, unit = #{unit},
where id = #{id}

mapper.select:
select u.id, u.soap_id, u.consumable_id, u.quantity_used, u.unit_price, u.unit, u.created, c.name as consumable_name, c.brand as consumable_brand, p.name as production_name, p.batch_number as production_batch_number from soap_consumables_usage u left join soap_consumables c on u.consumable_id = c.id left join soap_production p on u.soap_id = p.id
and p.owner_user_id = #{currentUserId}
order by u.id desc limit #{pageable.offset}, #{pageable.pageSize}
